/**
 * Os ciclos que sustentam a vida — porte de `componentes/viz/ciclos.js`.
 *
 * Água, carbono e nitrogênio não se gastam: circulam. O módulo pede que se monte
 * cada ciclo na ordem em que a matéria de fato anda, e a cena é o veredito — o
 * anel só ACENDE, e as partículas só voltam a correr, quando a ordem fecha o
 * laço. Enquanto não fecha, o planeta no centro fica cinza.
 *
 * **A cena virou 2D.** No legado ela era 3D, mas todos os nós ficavam em z = 0 e
 * os emblemas eram billboards — desenhos de canvas 2D colados de frente para a
 * câmera. Ou seja: já era um anel plano visto de frente, com o custo de um motor
 * 3D em volta. Aqui os emblemas são desenhados direto, com o mesmo código.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  paleta,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const PARTICULAS = 24;

/** Uma etapa já posicionada no anel, como o renderizador a entrega. */
interface Etapa {
  readonly id: string;
  readonly curto: string;
  readonly icone: string;
}

const ciclos: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /**
   * O emblema de cada estágio. São desenhos, e não emoji, porque emoji muda de
   * cara em cada sistema — e aqui a forma é o que se reconhece.
   */
  function emblema(
    ctx: CanvasRenderingContext2D,
    tipo: string,
    x: number,
    y: number,
    r: number,
  ): void {
    const cor = paleta();
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(r / 64, r / 64);
    ctx.lineWidth = 7;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (tipo === 'sol') {
      ctx.fillStyle = '#e8b81f';
      ctx.beginPath();
      ctx.arc(0, 0, 26, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#e8b81f';
      for (let i = 0; i < 8; i++) {
        const a = (i * Math.PI) / 4;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * 34, Math.sin(a) * 34);
        ctx.lineTo(Math.cos(a) * 46, Math.sin(a) * 46);
        ctx.stroke();
      }
    } else if (tipo === 'nuvem') {
      ctx.fillStyle = '#9fb4cc';
      for (const [cx, cy, cr] of [
        [-18, 10, 22],
        [8, 10, 26],
        [-4, -6, 24],
        [24, 12, 18],
      ]) {
        ctx.beginPath();
        ctx.arc(cx ?? 0, cy ?? 0, cr ?? 0, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (tipo === 'chuva') {
      ctx.fillStyle = '#9fb4cc';
      for (const [cx, cy, cr] of [
        [-14, -8, 20],
        [10, -8, 22],
        [-2, -20, 20],
      ]) {
        ctx.beginPath();
        ctx.arc(cx ?? 0, cy ?? 0, cr ?? 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.strokeStyle = cor.azulClaro;
      for (const dx of [-16, 0, 16]) {
        ctx.beginPath();
        ctx.moveTo(dx, 12);
        ctx.lineTo(dx - 6, 34);
        ctx.stroke();
      }
    } else if (tipo === 'humano') {
      ctx.fillStyle = '#d8a173';
      ctx.beginPath();
      ctx.arc(0, -22, 16, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#8a5a3a';
      ctx.beginPath();
      ctx.moveTo(0, -6);
      ctx.lineTo(0, 28);
      ctx.moveTo(0, 4);
      ctx.lineTo(-20, 18);
      ctx.moveTo(0, 4);
      ctx.lineTo(20, 18);
      ctx.moveTo(0, 28);
      ctx.lineTo(-14, 48);
      ctx.moveTo(0, 28);
      ctx.lineTo(14, 48);
      ctx.stroke();
    } else if (tipo === 'planta') {
      ctx.strokeStyle = '#2f8f4a';
      ctx.beginPath();
      ctx.moveTo(0, 44);
      ctx.lineTo(0, -8);
      ctx.stroke();
      ctx.fillStyle = '#3ba054';
      for (const lado of [-1, 1]) {
        ctx.beginPath();
        ctx.ellipse(lado * 16, 6, 16, 9, lado * 0.7, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.beginPath();
      ctx.ellipse(0, -14, 12, 16, 0, 0, Math.PI * 2);
      ctx.fill();
    } else if (tipo === 'o2') {
      ctx.fillStyle = cor.azul;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 60px system-ui, sans-serif';
      ctx.fillText('O', -14, 0);
      ctx.font = 'bold 40px system-ui, sans-serif';
      ctx.fillText('₂', 24, 12);
    } else if (tipo === 'raio') {
      ctx.fillStyle = '#e8b81f';
      ctx.beginPath();
      ctx.moveTo(8, -40);
      ctx.lineTo(-20, 6);
      ctx.lineTo(-2, 6);
      ctx.lineTo(-12, 40);
      ctx.lineTo(24, -6);
      ctx.lineTo(4, -6);
      ctx.closePath();
      ctx.fill();
    } else if (tipo === 'bacteria') {
      ctx.fillStyle = '#6aab58';
      ctx.beginPath();
      ctx.ellipse(0, 0, 30, 20, 0.4, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#4a9a3a';
      for (let i = 0; i < 8; i++) {
        const a = (i * Math.PI) / 4;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * 28, Math.sin(a) * 18);
        ctx.lineTo(Math.cos(a) * 40, Math.sin(a) * 26);
        ctx.stroke();
      }
    } else {
      ctx.strokeStyle = cor.fraco;
      ctx.beginPath();
      ctx.arc(0, 0, 26, 0, Math.PI * 2);
      ctx.stroke();
    }

    ctx.restore();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const sequencia = Array.isArray(info.seq) ? (info.seq as (Etapa | undefined)[]) : [];
    const total = typeof info.total === 'number' ? info.total : 3;
    const fechado = info.completoAtivo === true;
    const tudoOk = info.ok === true;
    const corDoCiclo = textoDe(info, 'cor') || cor.azulClaro;
    const nome = textoDe(info, 'nome');

    titulo(ctx, L, A, nome === '' ? 'A matéria circula' : `Ciclo ${nome.toLowerCase()}`);

    const cx = L / 2;
    const cy = A * 0.55;
    const R = Math.min(L, A) * 0.3;

    // O anel: apagado enquanto o laço não fecha, aceso quando fecha.
    ctx.strokeStyle = fechado ? corDoCiclo : cor.trilho;
    ctx.lineWidth = fechado ? 3.5 : 2;
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.stroke();

    // As partículas só correm no ciclo fechado — é a recompensa visual.
    if (fechado) {
      ctx.fillStyle = corDoCiclo;
      for (let i = 0; i < PARTICULAS; i++) {
        const a = t * 0.6 + (i / PARTICULAS) * Math.PI * 2;
        ctx.beginPath();
        ctx.arc(cx + Math.cos(a) * R, cy + Math.sin(a) * R, 3, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // O planeta no centro: cinza parado, colorido no ciclo fechado, verde vivo
    // quando os três fecham.
    const raioPlaneta = R * 0.34;
    if (tudoOk) {
      const pulso = 0.5 + Math.sin(t * 3) * 0.1;
      ctx.fillStyle = '#3ba054';
      ctx.beginPath();
      ctx.arc(cx, cy, raioPlaneta * (1 + pulso * 0.04), 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.fillStyle = fechado ? corDoCiclo : cor.trilho;
      ctx.beginPath();
      ctx.arc(cx, cy, raioPlaneta, 0, Math.PI * 2);
      ctx.fill();
    }

    // Os nós, na ordem montada. Vazio vira "?" — o que ainda falta posicionar.
    const raioEmblema = limitar(R * 0.26, 14, 30);
    for (let i = 0; i < total; i++) {
      const a = -Math.PI / 2 + (i / total) * Math.PI * 2;
      const x = cx + Math.cos(a) * R;
      const y = cy + Math.sin(a) * R;
      const etapa = sequencia[i];

      ctx.fillStyle = cor.fundo;
      ctx.strokeStyle = etapa === undefined ? cor.trilho : corDoCiclo;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(x, y, raioEmblema, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      if (etapa === undefined) {
        texto(ctx, '?', x, y, raioEmblema, { cor: cor.fraco, peso: 800 });
        continue;
      }

      emblema(ctx, etapa.icone, x, y, raioEmblema * 0.82);
      etiqueta(
        ctx,
        `${i + 1}. ${etapa.curto}`,
        x,
        y + raioEmblema + 12,
        limitar(A * 0.032, 8, 11),
        cor.texto,
        700,
      );
    }
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default ciclos;
